application.css:
* { box-sizing: border-box; }

:root {
  color: #172033;
  background: #f4f7fb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body { margin: 0; }
.page-shell { width: min(100% - 2rem,  fiftyrem); max-width: 50rem; margin: 0 auto; padding: 3rem 0; }
.page-header { margin-bottom: 2rem; }
.eyebrow { color: #315ca8; font-size: .8rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; margin: 0 0 .5rem; }
h1, h2 { line-height: 1.2; margin-top: 0; }
h1 { font-size: clamp(1.8rem, 5vw, 2.7rem); margin-bottom: .75rem; }
h2 { font-size: 1.35rem; margin-bottom: 1.25rem; }
.intro { color: #4c5870; margin: 0; }
.panel { background: #fff; border: 1px solid #d9e0eb; border-radius: .75rem; box-shadow: 0 5px 18px rgba(28, 43, 69, .06); margin-bottom: 1.5rem; padding: clamp(1.25rem, 4vw, 2rem); }
.form-grid { display: grid; gap: 1rem; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.field-wide { grid-column: 1 / -1; }
.field { min-width: 0; }
label { display: block; font-weight: 650; margin-bottom: .4rem; }
input, select { background: #fff; border: 1px solid #9aa8bc; border-radius: .4rem; color: #172033; font: inherit; min-height: 2.75rem; padding: .55rem .7rem; width: 100%; }
input:focus, select:focus, button:focus { outline: 3px solid #9cc4ff; outline-offset: 2px; }
input:user-invalid, select:user-invalid { border-color: #b42318; }
.error { color: #b42318; font-size: .88rem; margin: .3rem 0 0; min-height: 1.2em; }
.primary-button, .cancel-button { border: 0; border-radius: .4rem; cursor: pointer; font: inherit; font-weight: 700; padding: .7rem 1rem; }
.primary-button { background: #2457a6; color: #fff; margin-top: .5rem; }
.primary-button:hover { background: #1b4485; }
.cancel-button { background: #fcebea; color: #9b2118; }
.cancel-button:hover { background: #f8d7d4; }
.form-status { min-height: 1.4em; margin: 1rem 0 0; }
.form-status.error-message { color: #b42318; }
.section-heading { align-items: baseline; display: flex; gap: 1rem; justify-content: space-between; }
.booking-count { color: #59667b; font-size: .9rem; }
.confirmation { background: #e7f6ed; border: 1px solid #8cc9a4; border-radius: .4rem; color: #145c32; margin-bottom: 1rem; padding: .75rem 1rem; }
.booking-list { display: grid; gap: .85rem; }
.empty-state { color: #59667b; margin: 0; }
.booking { border: 1px solid #d9e0eb; border-left: 4px solid #315ca8; border-radius: .45rem; padding: 1rem; }
.booking.cancelled { border-left-color: #778399; opacity: .78; }
.booking-top { align-items: start; display: flex; gap: 1rem; justify-content: space-between; }
.booking-name { font-size: 1.05rem; font-weight: 750; margin: 0; }
.booking-details { color: #4c5870; margin: .35rem 0 0; }
.cancelled-label { color: #59667b; font-size: .8rem; font-weight: 700; text-transform: uppercase; }
[hidden] { display: none; }
@media (max-width:  fortyrem) { .page-shell { padding: 2rem 0; } .form-grid { grid-template-columns: 1fr; } .field-wide { grid-column: auto; } .booking-top { align-items: stretch; flex-direction: column; } .cancel-button { align-self: flex-start; } }

application.javascript:
const form = document.querySelector('#booking-form');
const dateInput = document.querySelector('#booking-date');
const list = document.querySelector('#booking-list');
const emptyState = document.querySelector('#empty-state');
const confirmation = document.querySelector('#booking-confirmation');
const count = document.querySelector('#booking-count');
const statusMessage = document.querySelector('#form-status');
const bookings = [];

function getToday() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function setDateMinimum() {
  dateInput.min = getToday();
}

function clearErrors() {
  document.querySelectorAll('.error').forEach((element) => { element.textContent = ''; });
  statusMessage.textContent = '';
  statusMessage.className = 'form-status';
}

function showValidationErrors() {
  const fields = [
    ['name', 'name-error', 'Please enter the customer name.'],
    ['email', 'email-error', 'Please enter a valid email address.'],
    ['date', 'date-error', 'Please choose today or a future date.'],
    ['time', 'time-error', 'Please choose an appointment time.'],
    ['type', 'type-error', 'Please select an appointment type.']
  ];
  let firstInvalid = null;
  fields.forEach(([name, errorId, message]) => {
    const field = form.elements[name];
    if (!field.checkValidity() || (name === 'date' && field.value < getToday())) {
      document.querySelector(`#${errorId}`).textContent = message;
      if (!firstInvalid) firstInvalid = field;
    }
  });
  if (firstInvalid) firstInvalid.focus();
  return !firstInvalid;
}

function formatDate(value) {
  return new Date(`${value}T00:00:00`).toLocaleDateString(undefined, { dateStyle: 'medium' });
}

function createBookingElement(booking) {
  const article = document.createElement('article');
  article.className = 'booking';
  article.dataset.testid = 'booking';
  article.dataset.status = booking.cancelled ? 'cancelled' : 'active';

  const top = document.createElement('div');
  top.className = 'booking-top';
  const content = document.createElement('div');
  const name = document.createElement('p');
  name.className = 'booking-name';
  name.dataset.testid = 'booking-name-display';
  name.textContent = booking.name;
  const details = document.createElement('p');
  details.className = 'booking-details';
  details.textContent = `${booking.type} · ${formatDate(booking.date)} at ${booking.time} · ${booking.email}`;
  content.append(name, details);
  top.appendChild(content);

  if (booking.cancelled) {
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'Cancelled';
    top.appendChild(label);
  } else {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'cancel-button';
    button.dataset.testid = 'booking-cancel';
    button.textContent = 'Cancel';
    button.addEventListener('click', () => cancelBooking(booking.id));
    top.appendChild(button);
  }
  article.appendChild(top);
  return article;
}

function renderBookings() {
  list.replaceChildren();
  if (bookings.length === 0) list.appendChild(emptyState);
  bookings.forEach((booking) => list.appendChild(createBookingElement(booking)));
  count.textContent = `${bookings.length} booking${bookings.length === 1 ? '' : 's'}`;
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (!booking) return;
  booking.cancelled = true;
  renderBookings();
}

function showConfirmation(booking) {
  confirmation.textContent = `Booking confirmed for ${booking.name} on ${formatDate(booking.date)} at ${booking.time}.`;
  confirmation.hidden = false;
}

function handleSubmit(event) {
  event.preventDefault();
  clearErrors();
  if (!showValidationErrors()) {
    statusMessage.textContent = 'Please correct the highlighted fields.';
    statusMessage.className = 'form-status error-message';
    return;
  }
  const data = new FormData(form);
  const booking = {
    id: `${Date.now()}-${bookings.length}`,
    name: data.get('name').trim(),
    email: data.get('email').trim(),
    date: data.get('date'),
    time: data.get('time'),
    type: data.get('type'),
    cancelled: false
  };
  bookings.push(booking);
  renderBookings();
  showConfirmation(booking);
  form.reset();
  setDateMinimum();
  confirmation.focus();
}

setDateMinimum();
form.addEventListener('submit', handleSubmit);
renderBookings();
